import { ThemeUtils } from './ui/theme-utils.js';
import { DetailsPanel } from './ui/details-panel.js';
import { SidebarManager } from './ui/sidebar-manager.js';
import { GraphEngine } from './graph/engine.js';

// Attach modules to window so that inline HTML onclick handlers
// (like those generated by SidebarManager and DetailsPanel) can access them.
window.ThemeUtils = ThemeUtils;
window.DetailsPanel = DetailsPanel;
window.SidebarManager = SidebarManager;
window.GraphEngine = GraphEngine;

window.addEventListener('DOMContentLoaded', () => {
  SidebarManager.init();
  GraphEngine.init();
  if (window.lucide) window.lucide.createIcons();
});
